{
  "meta": {
    "name": "Fitness Tracker",
    "description": "A fitness tracking app allowing users to log workouts and exercises, view their history, with premium members accessing advanced analytics and charts."
  },
  "entities": [
    {
      "name": "Workout",
      "ownable": true,
      "fields": [
        {
          "name": "date",
          "type": "date",
          "required": true
        },
        {
          "name": "duration",
          "type": "integer",
          "required": true,
          "label": "Duration (minutes)"
        },
        {
          "name": "type",
          "type": "enum",
          "required": true,
          "enumValues": [
            "cardio",
            "strength",
            "flexibility",
            "other"
          ],
          "default": "other"
        }
      ],
      "relations": [
        {
          "name": "exercises",
          "kind": "oneToMany",
          "target": "Exercise"
        }
      ]
    },
    {
      "name": "Exercise",
      "ownable": true,
      "fields": [
        {
          "name": "name",
          "type": "string",
          "required": true
        },
        {
          "name": "sets",
          "type": "integer"
        },
        {
          "name": "reps",
          "type": "integer"
        },
        {
          "name": "weight",
          "type": "number",
          "label": "Weight (kg/lbs)"
        }
      ],
      "relations": [
        {
          "name": "workout",
          "kind": "manyToOne",
          "target": "Workout",
          "required": true
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "member",
      "description": "Standard user",
      "isDefault": true
    },
    {
      "name": "premiumMember",
      "description": "User with access to premium features"
    }
  ],
  "permissions": [
    {
      "role": "member",
      "entity": "Workout",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "member",
      "entity": "Exercise",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "premiumMember",
      "entity": "Workout",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "premiumMember",
      "entity": "Exercise",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    }
  ],
  "pages": [
    {
      "name": "Workouts",
      "route": "/workouts",
      "type": "list",
      "entity": "Workout",
      "access": [
        "member",
        "premiumMember"
      ]
    },
    {
      "name": "New Workout",
      "route": "/workouts/new",
      "type": "form",
      "entity": "Workout",
      "access": [
        "member",
        "premiumMember"
      ]
    },
    {
      "name": "Workout Detail",
      "route": "/workouts/:id",
      "type": "detail",
      "entity": "Workout",
      "access": [
        "member",
        "premiumMember"
      ]
    },
    {
      "name": "Progress Analytics",
      "route": "/analytics",
      "type": "dashboard",
      "access": [
        "premiumMember"
      ],
      "requiresPlan": "premium",
      "widgets": [
        {
          "type": "chart",
          "label": "Workouts Over Time",
          "entity": "Workout",
          "chartType": "line",
          "xField": "date",
          "yField": "duration",
          "metric": "sum"
        },
        {
          "type": "stat",
          "label": "Total Workouts Logged",
          "entity": "Workout",
          "metric": "count"
        },
        {
          "type": "chart",
          "label": "Exercise Distribution",
          "entity": "Exercise",
          "chartType": "pie",
          "field": "name"
        }
      ]
    }
  ],
  "plans": [
    {
      "name": "free",
      "isDefault": true
    },
    {
      "name": "premium",
      "price": 9.99,
      "interval": "month",
      "features": [
        "progressAnalytics",
        "charts"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "premiumFeaturesGate",
      "requiresPlan": "premium",
      "gates": {
        "pages": [
          "Progress Analytics"
        ],
        "features": [
          "progressAnalytics",
          "charts"
        ]
      }
    },
    {
      "type": "ownership",
      "id": "workoutOwnership",
      "entity": "Workout"
    },
    {
      "type": "ownership",
      "id": "exerciseOwnership",
      "entity": "Exercise"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
